/** Placeholder lines in the templates, which a finished project replaces. */
export const STARTER_TEXT = ["A short line that says what this is and who it is for.", "Tell the story here.", "What it is.", "One sentence on the problem it solves and why it is better.", "A benefit, not a feature.", "It changed how I work.", "A happy customer", "Say what makes this one special.", "12 Your Street, Your Town", "(000) 000-0000", "hello@example.com", "Photo credits go here.", "hello@yourschool.example", "the green shed by the north ramp", "Jess Morales", "Kai Tran", "Amara Bello", "Sample numbers for this starter", "20 Sample Lane", "studio@yourstudio.example", "Lorem ipsum", "dummyimage.com", "Start Bootstrap", "Your Website 20", "Company Name", "free Bootstrap theme", "free bootstrap theme", "Wattle Terrace", "Riverbank Library", "A practice of seven in Redfern", "Seven people and never more than twelve projects"];

/** The files of one starter project, filled in with the project's title. */
export function templateFiles(name, title) {
  const template = TEMPLATES[name];
  if (!template) throw new Error(`No template called ${name}. Pick one of: ${Object.keys(TEMPLATES).join(", ")}.`);
  const clean = String(title).replace(/[<>]/g, "");
  const slug = String(title).toLowerCase().split(/\s+/).filter(Boolean).join("-") || "project";
  const initial = (String(title).match(/[\p{L}\p{N}]/u) || ["★"])[0].toUpperCase();
  const files = {};
  for (const [path, text] of Object.entries(template.files)) {
    files[path] = text.replaceAll("FCCTITLE0", clean).replaceAll("fcctitle0", slug).replaceAll("FCCINITIAL0", initial);
  }
  return files;
}
